/* lock-free ring: producer/consumer, hazard pointers */
static inline bool try_push_0(ring_t *r, void *p) { size_t t = atomic_load_explicit(&r->tail, memory_order_acquire); if (t - atomic_load_explicit(&r->head, memory_order_relaxed) == r->cap) return false; r->slot[t & r->mask] = p; atomic_store_explicit(&r->tail, t + 1, memory_order_release); return true; }
